import numpy as np
from qiskit.circuit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    """
    Grover phase oracle for subset sum: a = [13, 4, 4, 2, 6], target T = 27.
    Marks states where sum of selected elements equals 27.
    """
    a = [13, 4, 4, 2, 6]
    target = 27

    # Use 5 ancilla qubits for the sum
    sum_qubits = ancilla_qubits[:5]

    # Add each element to sum (controlled addition using bitwise XOR)
    for i, val in enumerate(a):
        if val == 0:
            continue
        bits = [int(b) for b in format(val, '05b')]
        for j, bit in enumerate(bits):
            if bit:
                qc.cx(problem_qubits[i], sum_qubits[j])

    # Check if sum == 27 (binary: 11011 LSB first = [1,1,0,1,1])
    target_bits = [1, 1, 0, 1, 1]  # LSB first

    # Flip bits where target is 0
    for j, bit in enumerate(target_bits):
        if bit == 0:
            qc.x(sum_qubits[j])

    # Apply multi-controlled Z using the last sum qubit as target
    qc.h(sum_qubits[4])
    qc.mcx(sum_qubits[:4], sum_qubits[4])
    qc.h(sum_qubits[4])

    # Unflip bits
    for j, bit in enumerate(target_bits):
        if bit == 0:
            qc.x(sum_qubits[j])

    # Uncompute additions (reverse order)
    for i, val in reversed(list(enumerate(a))):
        if val == 0:
            continue
        bits = [int(b) for b in format(val, '05b')]
        for j, bit in enumerate(bits):
            if bit:
                qc.cx(problem_qubits[i], sum_qubits[j])

